    rows = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = re.match(r"- \*\*(oauth-s02-t04-\d+)\*\* \| System: (\S+) \| Status: (\S+) \|", line)
            if m:
                rows[m.group(1)] = (m.group(2), m.group(3))
    return rows

