            obj = json.loads(line)
            rows[obj["case"]] = (obj["system"], obj["status"], obj["note"])
    return rows

def parse_csv(path):
    rows = {}
    with open(path, encoding="utf-8", newline="") as f:
        for r in csv.DictReader(f):
            rows[r["case"]] = (r["system"], r["status"], r["note"])
    return rows

def parse_yaml(path):
