import json, csv, re

def parse_md(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = re.match(r'- \*\*(oauth-s02-t08-\d+)\*\* \| System: ([^|]+) \| Status: ([^|]+) \| Evidence: (.*)', line.strip())
            if m:
                case, system, status, note = m.groups()
                out[case] = (system.strip(), status.strip(), note.strip())
    return out

def parse_jsonl(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            out[d['case']] = (d['system'], d['status'], d['note'])
    return out

def parse_csv(path):
    out = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            out[row['case']] = (row['system'], row['status'], row['note'])
    return out

def parse_yaml(path):
    out = {}
    case = system = status = note = None
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\n')
            if line.startswith('- case:'):
                case = line.split(':',1)[1].strip()
            elif line.strip().startswith('system:'):
                system = line.split(':',1)[1].strip()
            elif line.strip().startswith('status:'):
                status = line.split(':',1)[1].strip()
            elif line.strip().startswith('note:'):
                note = line.split(':',1)[1].strip().strip('\"')
                out[case] = (system, status, note)
    return out

md = parse_md('oauth-s02-t08-evidence-01.md')
jl = parse_jsonl('oauth-s02-t08-evidence-02.jsonl')
cv = parse_csv('oauth-s02-t08-evidence-03.csv')
yl = parse_yaml('oauth-s02-t08-evidence-04.yaml')

print('md cases:', len(md), min(md), max(md))
print('jsonl cases:', len(jl), min(jl), max(jl))
print('csv cases:', len(cv), min(cv), max(cv))
print('yaml cases:', len(yl), min(yl), max(yl))

def check_contiguous(d, prefix='oauth-s02-t08-'):
    nums = sorted(int(c.replace(prefix,'')) for c in d)
    expected = list(range(1, len(nums)+1))
    return nums == expected, len(nums), (len(nums)==len(set(nums)))

for name, d in [('md', md), ('jsonl', jl), ('csv', cv), ('yaml', yl)]:
    contig, n, nodup = check_contiguous(d)
    print(name, 'contiguous_no_gaps:', contig, 'count:', n, 'no_duplicates:', nodup)

common = set(md) & set(jl) & set(cv) & set(yl)
print('common cases:', len(common), min(common), max(common))

mismatches = []
for case in sorted(common):
    vals = {'md': md[case], 'jsonl': jl[case], 'csv': cv[case], 'yaml': yl[case]}
    if len(set(vals.values())) > 1:
        mismatches.append((case, vals))
print('mismatches over common range:', len(mismatches))

# md/yaml full comparison
common_my = set(md) & set(yl)
mismatches_my = [c for c in common_my if md[c] != yl[c]]
print('md/yaml mismatches (', len(common_my), 'common):', len(mismatches_my))

# extended range: md/csv/yaml beyond jsonl (55-56)
extended = (set(md) & set(cv) & set(yl)) - set(jl)
mismatches_ext = [c for c in extended if not (md[c]==cv[c]==yl[c])]
print('extended range (md/csv/yaml only, beyond jsonl):', sorted(extended), 'mismatches:', len(mismatches_ext))

csv_only = set(cv) - set(md)
print('csv-only cases:', sorted(csv_only))

def pairing_violations(d):
    pairs = {}
    violations = 0
    for case, (system, status, note) in d.items():
        if system in pairs and pairs[system] != status:
            violations += 1
        pairs[system] = status
    return violations, pairs

for name, d in [('md', md), ('jsonl', jl), ('csv', cv), ('yaml', yl)]:
    v, p = pairing_violations(d)
    print(name, 'pairing violations:', v, p)
