import re, json, csv

def parse_md(path):
    d = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line.startswith('- **'):
                continue
            m = re.match(r'- \*\*(oauth-s02-t10-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)', line)
            if not m:
                print("UNPARSED MD LINE:", line)
                continue
            case, system, status, note = m.groups()
            d[case] = (system, status, note)
    return d

def parse_jsonl(path):
    d = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            d[obj['case']] = (obj['system'], obj['status'], obj['note'])
    return d

def parse_csv(path):
    d = {}
    with open(path, encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            d[row['case']] = (row['system'], row['status'], row['note'])
    return d

def parse_yaml(path):
    d = {}
    with open(path, encoding='utf-8') as f:
        lines = f.readlines()
    case = system = status = None
    note = None
    for line in lines:
        line = line.rstrip('\n')
        if line.startswith('- case:'):
            if case is not None:
                d[case] = (system, status, note)
            case = line.split(':',1)[1].strip()
            system = status = note = None
        elif line.strip().startswith('system:'):
            system = line.split(':',1)[1].strip()
        elif line.strip().startswith('status:'):
            status = line.split(':',1)[1].strip()
        elif line.strip().startswith('note:'):
            note = line.split(':',1)[1].strip().strip('"')
    if case is not None:
        d[case] = (system, status, note)
    return d

md = parse_md("oauth-s02-t10-evidence-01.md")
jsonl = parse_jsonl("oauth-s02-t10-evidence-02.jsonl")
csvd = parse_csv("oauth-s02-t10-evidence-03.csv")
yaml = parse_yaml("oauth-s02-t10-evidence-04.yaml")

print("md count:", len(md))
print("jsonl count:", len(jsonl))
print("csv count:", len(csvd))
print("yaml count:", len(yaml))

def case_num(c):
    return int(c.split('-')[-1])

for name, d in [("md", md), ("jsonl", jsonl), ("csv", csvd), ("yaml", yaml)]:
    nums = sorted(case_num(c) for c in d)
    print(name, "min:", nums[0], "max:", nums[-1], "contiguous:", nums == list(range(nums[0], nums[-1]+1)), "duplicates:", len(nums) != len(set(nums)))

# cross-file comparison on common keys
sets = {"md": set(md), "jsonl": set(jsonl), "csv": set(csvd), "yaml": set(yaml)}
common = set.intersection(*sets.values())
print("common cases across all four:", len(common))

mismatches = []
for c in sorted(common, key=case_num):
    vals = {"md": md[c], "jsonl": jsonl[c], "csv": csvd[c], "yaml": yaml[c]}
    if len(set(vals.values())) > 1:
        mismatches.append((c, vals))
print("mismatches on common cases:", len(mismatches))
for m in mismatches[:20]:
    print(m)

# unique per-file cases (not in intersection of all 4)
for name, d in sets.items():
    others = set.union(*[v for k,v in sets.items() if k != name])
    uniq = d - set.intersection(*[v for k,v in sets.items() if k != name])
    print(name, "cases not present in ALL other three files:", len(uniq))

# csv widest - what's beyond md/yaml (1-114)?
csv_only = sorted([c for c in csvd if case_num(c) > 114], key=case_num)
print("csv cases beyond 114:", len(csv_only), csv_only[:5], csv_only[-5:] if csv_only else None)

jsonl_missing_from_top = sorted([c for c in md if case_num(c) > max(case_num(x) for x in jsonl)], key=case_num)
print("jsonl max:", max(case_num(x) for x in jsonl))

# system-status pairing consistency across all records combined
pairing = {}
violations = []
all_records = {}
for d in (md, jsonl, csvd, yaml):
    all_records.update(d)
for c, (system, status, note) in all_records.items():
    if system in pairing and pairing[system] != status:
        violations.append((c, system, status, pairing[system]))
    else:
        pairing[system] = status
print("system->status pairing:", pairing)
print("pairing violations:", len(violations))
for v in violations[:20]:
    print(v)

# note text sanity: does any note mention duplicate reconciliation policy/outcome specifics?
keywords = ["preserve", "reject", "conflict", "first", "commit", "idempotent", "reconcil"]
hits = []
for c, (system, status, note) in all_records.items():
    low = note.lower()
    for k in keywords:
        if k in low and k not in ("first", "commit"):
            hits.append((c, k, note))
print("keyword hits (excluding boilerplate 'first'/'commit'):", len(hits))
for h in hits[:20]:
    print(h)
EOF

