cd "/c/Users/Billy/AppData/Local/Temp/lcm-live-qbw0j7ps/oauth-s02-imported-pending/maintenance/inputs/oauth-s02/operator-handoff-logs" && python - <<'EOF'
import re, json, csv

def parse_md(path):
    d = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line.startswith('- **'):
                continue
            m = re.match(r'- \*\*(oauth-s02-t11-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)', line)
            if not m:
                print("UNPARSED MD LINE:", line)
                continue
            case, system, status, note = m.groups()
            d[case] = (system, status, note)
    return d

def parse_jsonl(path):
    d = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            d[obj['case']] = (obj['system'], obj['status'], obj['note'])
    return d

def parse_csv(path):
    d = {}
    with open(path, encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            d[row['case']] = (row['system'], row['status'], row['note'])
    return d

def parse_yaml(path):
    d = {}
    with open(path, encoding='utf-8') as f:
        lines = f.readlines()
    case = system = status = None
    note = None
    for line in lines:
        line = line.rstrip('\n')
        if line.startswith('- case:'):
            if case is not None:
                d[case] = (system, status, note)
            case = line.split(':',1)[1].strip()
            system = status = note = None
        elif line.strip().startswith('system:'):
            system = line.split(':',1)[1].strip()
        elif line.strip().startswith('status:'):
            status = line.split(':',1)[1].strip()
        elif line.strip().startswith('note:'):
            note = line.split(':',1)[1].strip().strip('"')
    if case is not None:
        d[case] = (system, status, note)
    return d

md = parse_md("oauth-s02-t11-evidence-01.md")
jsonl = parse_jsonl("oauth-s02-t11-evidence-02.jsonl")
csvd = parse_csv("oauth-s02-t11-evidence-03.csv")
yaml = parse_yaml("oauth-s02-t11-evidence-04.yaml")

print("md count:", len(md))
print("jsonl count:", len(jsonl))
print("csv count:", len(csvd))
print("yaml count:", len(yaml))

def case_num(c):
    return int(c.split('-')[-1])

for name, d in [("md", md), ("jsonl", jsonl), ("csv", csvd), ("yaml", yaml)]:
    nums = sorted(case_num(c) for c in d)
    print(name, "min:", nums[0], "max:", nums[-1], "contiguous:", nums == list(range(nums[0], nums[-1]+1)), "duplicates:", len(nums) != len(set(nums)))

sets = {"md": set(md), "jsonl": set(jsonl), "csv": set(csvd), "yaml": set(yaml)}
common = set.intersection(*sets.values())
print("common cases across all four:", len(common))

mismatches = []
for c in sorted(common, key=case_num):
    vals = {"md": md[c], "jsonl": jsonl[c], "csv": csvd[c], "yaml": yaml[c]}
    if len(set(vals.values())) > 1:
        mismatches.append((c, vals))
print("mismatches on common cases:", len(mismatches))
for m in mismatches[:20]:
    print(m)

md_yaml_max = max(case_num(x) for x in md)
jsonl_max = max(case_num(x) for x in jsonl)
csv_max = max(case_num(x) for x in csvd)
print("md/yaml max:", md_yaml_max, "jsonl max:", jsonl_max, "csv max:", csv_max)

csv_only = sorted([c for c in csvd if case_num(c) > md_yaml_max], key=case_num)
print("csv cases beyond md/yaml max:", len(csv_only), csv_only[:3], csv_only[-3:] if csv_only else None)

md_yaml_extra = sorted([c for c in md if case_num(c) > jsonl_max], key=case_num)
print("md/yaml cases beyond jsonl max:", len(md_yaml_extra))
# verify md vs yaml equal on these extra
extra_mismatches = [c for c in md_yaml_extra if md[c] != yaml[c]]
print("md vs yaml mismatches on extra range:", len(extra_mismatches))
# verify csv matches md/yaml on these extra where present (should, since csv covers up to higher)
extra_vs_csv_mismatches = [c for c in md_yaml_extra if c in csvd and csvd[c] != md[c]]
print("csv vs md mismatches on extra range (where csv has the case):", len(extra_vs_csv_mismatches))

pairing = {}
violations = []
all_records = {}
for d in (md, jsonl, csvd, yaml):
    all_records.update(d)
for c, (system, status, note) in all_records.items():
    if system in pairing and pairing[system] != status:
        violations.append((c, system, status, pairing[system]))
    else:
        pairing[system] = status
print("system->status pairing:", pairing)
print("pairing violations:", len(violations))
for v in violations[:20]:
    print(v)

keywords = ["preserve", "reject", "conflict", "reconcil", "idempotent", "handoff", "operator", "escalat"]
hits = []
for c, (system, status, note) in all_records.items():
    low = note.lower()
    for k in keywords:
        if k in low and k not in ("handoff", "operator"):
            hits.append((c, k, note))
print("keyword hits (excluding boilerplate handoff/operator):", len(hits))
for h in hits[:20]:
    print(h)
